<template>
  <div class="json-editor">
    <el-input
      v-model="text"
      type="textarea"
      :rows="rows"
      :placeholder="placeholder"
      :disabled="disabled"
      class="json-textarea"
      @blur="onBlur"
    />
    <div v-if="error" class="json-error">{{ error }}</div>
  </div>
</template>

<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'

const props = defineProps<{
  modelValue?: Record<string, unknown> | string | null
  rows?: number
  placeholder?: string
  disabled?: boolean
}>()

const emit = defineEmits<{
  'update:modelValue': [value: Record<string, unknown>]
}>()

const { t } = useI18n()

const rows = props.rows || 6

function stringify(value: unknown): string {
  if (value === null || value === undefined) return ''
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value)
      return JSON.stringify(parsed, null, 2)
    } catch {
      return value
    }
  }
  return JSON.stringify(value, null, 2)
}

const text = ref(stringify(props.modelValue))
const error = ref('')

watch(
  () => props.modelValue,
  (val) => {
    text.value = stringify(val)
  }
)

function onBlur() {
  error.value = ''
  const trimmed = text.value.trim()
  if (!trimmed) {
    emit('update:modelValue', {})
    return
  }
  try {
    const parsed = JSON.parse(trimmed)
    if (parsed !== null && typeof parsed !== 'object') {
      throw new Error(t('common.jsonMustBeObject'))
    }
    emit('update:modelValue', (parsed as Record<string, unknown>) || {})
  } catch (e: any) {
    error.value = e.message || t('common.jsonInvalid')
  }
}
</script>

<style scoped>
.json-textarea :deep(textarea) {
  font-family: 'Courier New', monospace;
}

.json-error {
  color: var(--el-color-danger);
  font-size: 12px;
  margin-top: 4px;
}
</style>
